function adTotals(x){if(!x)return null;const out={};for(const k of ['investimento','receita','cliques','impressoes','unidades'])out[k]=sum(x.campanhas,c=>c.metricas[k]);out.roas=out.investimento?out.receita/out.investimento:null;out.acos=out.receita?out.investimento/out.receita:null;return out}
